package com.jackandpaws.controller; import com.jackandpaws.dto.AuthDtos.UserResponse;import com.jackandpaws.service.CurrentUserService;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/users") public class UserController{final CurrentUserService current;public UserController(CurrentUserService c){current=c;}@GetMapping("/me")public UserResponse me(){return UserResponse.of(current.get());}}
